 321→// ---------------------------------------------------------------------------
 322→// Validation
 323→// ---------------------------------------------------------------------------
 324→
 325→/// Validate that a target is well-formed and can be serviced.
 326→///
 327→/// Checks:
 328→/// 1. The target kind is valid for its chain family.
 329→/// 2. Address is present when required (all kinds except topic_filter, protocol).
 330→/// 3. filter_spec is present when required (topic_filter, protocol).
 331→pub fn validate_target(target: &IndexTarget) -> Result<(), Vec<String>> {
 332→    let mut errors = Vec::new();
 333→
 334→    // Rule 1: kind must be valid for chain family
 335→    if !target.kind.valid_for_chain_family(target.chain_family) {
 336→        errors.push(format!(
 337→            "target kind {:?} is not valid for chain family {:?}",
 338→            target.kind, target.chain_family
 339→        ));
 340→    }
 341→
 342→    // Rule 2: address required for simple target kinds
 343→    let address_required = !matches!(target.kind, TargetKind::TopicFilter | TargetKind::Protocol);
 344→    if address_required && target.address.as_ref().is_none_or(|a| a.is_empty()) {
 345→        errors.push(format!(
 346→            "target kind {:?} requires a non-empty address",
 347→            target.kind
 348→        ));
 349→    }
 350→
 351→    // Rule 3: filter_spec required for complex target kinds
 352→    let filter_required = matches!(target.kind, TargetKind::TopicFilter | TargetKind::Protocol);
 353→    if filter_required && target.filter_spec.is_none() {
 354→        errors.push(format!(
 355→            "target kind {:?} requires filter_spec",
 356→            target.kind
 357→        ));
 358→    }
 359→
 360→    if errors.is_empty() {
 361→        Ok(())
 362→    } else {
 363→        Err(errors)
 364→    }
 365→}
