 378→    fn make_target(
 379→        kind: TargetKind,
 380→        chain_family: ChainFamily,
 381→        address: Option<&str>,
 382→        filter_spec: Option<serde_json::Value>,
 383→        mode: TargetMode,
 384→    ) -> IndexTarget {
 385→        let now = Utc::now();
 386→        IndexTarget {
 387→            id: Uuid::new_v4(),
 388→            kind,
 389→            network: "test-mainnet".to_string(),
 390→            chain_family,
 391→            address: address.map(|s| s.to_string()),
 392→            filter_spec,
 393→            mode,
 394→            label: None,
