 49→/// Tracks the last processed slot for checkpoint-based reconnection.
 50→#[derive(Clone)]
 51→pub struct SlotCheckpoint {
 52→    last_slot: Arc<AtomicU64>,
 53→}
 54→
 55→impl Default for SlotCheckpoint {
 56→    fn default() -> Self {
 57→        Self::new()
 58→    }
 59→}
 60→
 61→impl SlotCheckpoint {
 62→    pub fn new() -> Self {
 63→        Self {
 64→            last_slot: Arc::new(AtomicU64::new(0)),
 65→        }
 66→    }
 67→
 68→    pub fn update(&self, slot: u64) {
 69→        self.last_slot.fetch_max(slot, Ordering::Relaxed);
 70→    }
 71→
 72→    pub fn get(&self) -> u64 {
 73→        self.last_slot.load(Ordering::Relaxed)
 74→    }
