   6→use alloy::consensus::Transaction as TransactionTrait;
   7→use alloy::primitives::{Address, B256};
   8→use alloy::providers::{Provider, ProviderBuilder};
   9→use alloy::rpc::types::{Filter, Log};
  10→use chrono::Utc;
  11→use governor::{Quota, RateLimiter};
  12→use serde_json::json;
  13→use spectraplex_core::connector::{
  14→    extract_filter_spec, Connector, ConnectorCapabilities, TopicFilterSpec, TypedFilterSpec,
  15→};
  16→use spectraplex_core::models::{Chain, ChainIngestor, IndexerCheckpoint, Transaction};
  17→use spectraplex_core::v2::{
  18→    ChainFamily, IndexTarget, IngestionBatch, RawTransaction, TargetKind, TargetMode,
  19→};
  20→use tracing::warn;
  21→use uuid::Uuid;
  22→
  23→/// Maximum block range per eth_getLogs request.
  24→const DEFAULT_BLOCK_CHUNK: u64 = 2000;
  25→
  26→/// ERC-20 Transfer event signature: keccak256("Transfer(address,address,uint256)")
  27→const ERC20_TRANSFER_TOPIC: &str =
  28→    "0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef";
  29→
  30→/// EVM chain adapter that fetches logs and transactions via JSON-RPC.
  31→///
  32→/// Implements both the legacy `ChainIngestor` trait (wallet-only, V1) and
  33→/// the V2 `Connector` trait with correct semantics for wallet, contract,
  34→/// and topic_filter target kinds.
  35→pub struct EvmAdapter {
  36→    provider: Arc<dyn Provider + Send + Sync>,
  37→    rate_limiter: Arc<
  38→        RateLimiter<
  39→            governor::state::NotKeyed,
  40→            governor::state::InMemoryState,
  41→            governor::clock::DefaultClock,
  42→        >,
  43→    >,
  44→    block_chunk: u64,
  45→    network: String,
  46→}
  47→
  48→impl EvmAdapter {
  49→    /// Create a new adapter connected to an EVM-compatible RPC endpoint.
  50→    pub fn new(rpc_url: &str) -> anyhow::Result<Self> {
  51→        let url: reqwest::Url = rpc_url.parse()?;
  52→        let client = reqwest::Client::builder()
  53→            .timeout(Duration::from_secs(30))
  54→            .connect_timeout(Duration::from_secs(10))
  55→            .build()?;
  56→        let provider = ProviderBuilder::new().connect_reqwest(client, url);
  57→
  58→        // 5 requests per second by default (safe for public RPCs)
  59→        let quota = Quota::per_second(NonZeroU32::new(5).unwrap());
  60→        let limiter = RateLimiter::direct(quota);
  61→
  62→        Ok(Self {
  63→            provider: Arc::new(provider),
  64→            rate_limiter: Arc::new(limiter),
  65→            block_chunk: DEFAULT_BLOCK_CHUNK,
  66→            network: "ethereum-mainnet".to_string(),
  67→        })
  68→    }
  69→
  70→    /// Set a custom block chunk size for `eth_getLogs` range queries.
  71→    pub fn with_block_chunk(mut self, chunk: u64) -> Self {
  72→        self.block_chunk = chunk;
  73→        self
  74→    }
  75→
  76→    /// Override the network identifier (e.g. "base-mainnet", "arbitrum-mainnet").
  77→    pub fn with_network(mut self, network: &str) -> Self {
  78→        self.network = network.to_string();
  79→        self
  80→    }
  81→
  82→    // -----------------------------------------------------------------------
  83→    // Low-level log fetching methods
  84→    // -----------------------------------------------------------------------
  85→
  86→    /// Fetch logs for a given contract address across a block range, chunked
  87→    /// to avoid RPC limits.
  88→    ///
  89→    /// This is the original address-filter method. Correct for contract targets
  90→    /// (returns all events emitted *by* that contract).
  91→    pub async fn fetch_logs(
  92→        &self,
  93→        address: Address,
  94→        from_block: u64,
  95→        to_block: u64,
  96→    ) -> anyhow::Result<Vec<Log>> {
  97→        let mut all_logs = Vec::new();
  98→        let mut start = from_block;
  99→
 100→        while start <= to_block {
 101→            let end = std::cmp::min(start + self.block_chunk - 1, to_block);
 102→
 103→            self.rate_limiter.until_ready().await;
 104→
 105→            let filter = Filter::new()
 106→                .address(address)
 107→                .from_block(start)
 108→                .to_block(end);
 109→
 110→            let logs = self.provider.get_logs(&filter).await?;
 111→            all_logs.extend(logs);
 112→
 113→            start = end + 1;
 114→        }
 115→
 116→        Ok(all_logs)
 117→    }
 118→
 119→    /// Fetch logs by topic filters with an optional address constraint.
 120→    ///
 121→    /// Generalizes `fetch_logs` by accepting up to 4 topic-position filters
 122→    /// and an optional set of contract addresses. This is the building block
 123→    /// for wallet-based topic queries and arbitrary topic_filter targets.
 124→    #[allow(clippy::too_many_arguments)]
 125→    pub async fn fetch_logs_by_topics(
 126→        &self,
 127→        addresses: &[Address],
 128→        topic0: Option<B256>,
 129→        topic1: Option<B256>,
 130→        topic2: Option<B256>,
 131→        topic3: Option<B256>,
 132→        from_block: u64,
 133→        to_block: u64,
 134→    ) -> anyhow::Result<Vec<Log>> {
 135→        let mut all_logs = Vec::new();
 136→        let mut start = from_block;
 137→
 138→        while start <= to_block {
 139→            let end = std::cmp::min(start + self.block_chunk - 1, to_block);
 140→
 141→            self.rate_limiter.until_ready().await;
 142→
 143→            let mut filter = Filter::new().from_block(start).to_block(end);
 144→
 145→            if !addresses.is_empty() {
 146→                filter = filter.address(addresses.to_vec());
 147→            }
 148→            if let Some(t0) = topic0 {
 149→                filter = filter.event_signature(t0);
 150→            }
 151→            if let Some(t1) = topic1 {
 152→                filter = filter.topic1(t1);
 153→            }
 154→            if let Some(t2) = topic2 {
 155→                filter = filter.topic2(t2);
 156→            }
 157→            if let Some(t3) = topic3 {
 158→                filter = filter.topic3(t3);
 159→            }
 160→
 161→            let logs = self.provider.get_logs(&filter).await?;
 162→            all_logs.extend(logs);
 163→
 164→            start = end + 1;
 165→        }
 166→
 167→        Ok(all_logs)
 168→    }
 169→
 170→    /// Fetch ERC-20 Transfer logs involving a wallet address.
 171→    ///
 172→    /// Issues two `eth_getLogs` calls per chunk:
 173→    /// 1. Transfer events with wallet in topic\[1\] (sender / outgoing)
 174→    /// 2. Transfer events with wallet in topic\[2\] (receiver / incoming)
 175→    ///
 176→    /// Results are deduplicated by (tx_hash, log_index) to handle the case
 177→    /// where the wallet sends tokens to itself.
 178→    pub async fn fetch_wallet_erc20_logs(
 179→        &self,
 180→        wallet: Address,
 181→        from_block: u64,
 182→        to_block: u64,
 183→    ) -> anyhow::Result<Vec<Log>> {
 184→        let transfer_topic = parse_b256(ERC20_TRANSFER_TOPIC)?;
 185→        let wallet_padded = address_to_topic(wallet);
 186→
 187→        // Outgoing: wallet in topic[1] (from)
 188→        let outgoing = self
 189→            .fetch_logs_by_topics(
 190→                &[],
 191→                Some(transfer_topic),
 192→                Some(wallet_padded),
 193→                None,
 194→                None,
 195→                from_block,
 196→                to_block,
 197→            )
 198→            .await?;
 199→
 200→        // Incoming: wallet in topic[2] (to)
 201→        let incoming = self
 202→            .fetch_logs_by_topics(
 203→                &[],
 204→                Some(transfer_topic),
 205→                None,
 206→                Some(wallet_padded),
 207→                None,
 208→                from_block,
 209→                to_block,
 210→            )
 211→            .await?;
 212→
 213→        // Deduplicate by (tx_hash, log_index)
 214→        let mut seen = HashSet::new();
 215→        let mut result = Vec::new();
 216→        for log in outgoing.into_iter().chain(incoming) {
 217→            let key = (log.transaction_hash, log.log_index);
 218→            if seen.insert(key) {
 219→                result.push(log);
 220→            }
 221→        }
 222→
 223→        Ok(result)
 224→    }
 225→
 226→    // -----------------------------------------------------------------------
 227→    // Transaction enrichment
 228→    // -----------------------------------------------------------------------
 229→
 230→    /// Fetch transaction-level details (value, from, to) and receipt fields
 231→    /// (gas_used, effective_gas_price) for each unique tx hash in the logs.
 232→    async fn enrich_tx_data(
 233→        &self,
 234→        logs: &[Log],
 235→    ) -> HashMap<String, (serde_json::Value, serde_json::Value)> {
 236→        let mut seen_tx_hashes: HashMap<String, (serde_json::Value, serde_json::Value)> =
 237→            HashMap::new();
 238→
 239→        for log in logs {
 240→            let tx_hash_b256 = match log.transaction_hash {
 241→                Some(h) => h,
 242→                None => continue,
 243→            };
 244→            let tx_hash = format!("{tx_hash_b256:#x}");
 245→
 246→            if seen_tx_hashes.contains_key(&tx_hash) {
 247→                continue;
 248→            }
 249→
 250→            let mut tx_fields = json!({});
 251→            let mut receipt_fields = json!({});
 252→
 253→            self.rate_limiter.until_ready().await;
 254→            match self.provider.get_transaction_by_hash(tx_hash_b256).await {
 255→                Ok(Some(full_tx)) => {
 256→                    let value = full_tx.inner.value();
 257→                    let from = full_tx.inner.signer();
 258→                    let to = full_tx.inner.to().map(|a| format!("{a:#x}"));
 259→                    tx_fields = json!({
 260→                        "value": format!("{value:#x}"),
 261→                        "from": format!("{from:#x}"),
 262→                        "to": to,
 263→                    });
 264→                }
 265→                Ok(None) => {}
 266→                Err(e) => {
 267→                    warn!(tx_hash = %tx_hash, error = %e, "Failed to fetch transaction");
 268→                }
 269→            }
 270→
 271→            self.rate_limiter.until_ready().await;
 272→            match self.provider.get_transaction_receipt(tx_hash_b256).await {
 273→                Ok(Some(receipt)) => {
 274→                    receipt_fields = json!({
 275→                        "gas_used": format!("{:#x}", receipt.gas_used),
 276→                        "effective_gas_price": format!("{:#x}", receipt.effective_gas_price),
 277→                    });
 278→                }
 279→                Ok(None) => {}
 280→                Err(e) => {
 281→                    warn!(tx_hash = %tx_hash, error = %e, "Failed to fetch receipt");
 282→                }
 283→            }
 284→
 285→            seen_tx_hashes.insert(tx_hash, (tx_fields, receipt_fields));
 286→        }
 287→
 288→        seen_tx_hashes
 289→    }
 290→
 291→    // -----------------------------------------------------------------------
 292→    // V2 RawTransaction conversion
 293→    // -----------------------------------------------------------------------
 294→
 295→    /// Convert enriched logs into V2 `RawTransaction` records.
 296→    ///
 297→    /// Attaches tx-level fields (value, from, to, gas) only to the first log
 298→    /// per transaction hash to avoid duplicate gas fee / value entries in the
 299→    /// downstream parser.
 300→    fn logs_to_raw_transactions(
 301→        &self,
 302→        logs: &[Log],
 303→        enrichment: &HashMap<String, (serde_json::Value, serde_json::Value)>,
 304→        source: &str,
 305→    ) -> Vec<RawTransaction> {
 306→        let mut records = Vec::new();
 307→        let mut emitted_tx_hashes = HashSet::new();
 308→
 309→        for log in logs {
 310→            let tx_hash = match log.transaction_hash {
 311→                Some(h) => format!("{h:#x}"),
 312→                None => continue,
 313→            };
 314→
 315→            let block_timestamp = log.block_timestamp.unwrap_or(0);
 316→
 317→            let mut raw_metadata = json!({
 318→                "log_index": log.log_index,
 319→                "block_number": log.block_number,
 320→                "block_hash": log.block_hash.map(|h| format!("{h:#x}")),
 321→                "transaction_hash": &tx_hash,
 322→                "address": format!("{:#x}", log.address()),
 323→                "topics": log.topics().iter().map(|t| format!("{t:#x}")).collect::<Vec<_>>(),
 324→                "data": format!("0x{}", alloy::hex::encode(log.data().data.as_ref())),
 325→            });
 326→
 327→            let is_first_log = emitted_tx_hashes.insert(tx_hash.clone());
 328→            if is_first_log {
 329→                if let Some((tx_fields, receipt_fields)) = enrichment.get(&tx_hash) {
 330→                    if let Some(obj) = raw_metadata.as_object_mut() {
 331→                        if let Some(tx_obj) = tx_fields.as_object() {
 332→                            obj.extend(tx_obj.iter().map(|(k, v)| (k.clone(), v.clone())));
 333→                        }
 334→                        if let Some(rx_obj) = receipt_fields.as_object() {
 335→                            obj.extend(rx_obj.iter().map(|(k, v)| (k.clone(), v.clone())));
 336→                        }
 337→                    }
 338→                }
 339→            }
 340→
 341→            let timestamp = i64::try_from(block_timestamp).unwrap_or(i64::MAX);
 342→
 343→            records.push(RawTransaction {
 344→                id: Uuid::new_v4(),
 345→                network: self.network.clone(),
 346→                tx_hash,
 347→                timestamp,
 348→                block_number: log.block_number.map(|n| n as i64),
 349→                raw_metadata,
 350→                source: source.to_string(),
 351→                ingestion_run_id: None,
 352→                ingested_at: Utc::now(),
 353→            });
 354→        }
 355→
 356→        records
 357→    }
 358→
 359→    // -----------------------------------------------------------------------
 360→    // V2 Connector backfill paths
 361→    // -----------------------------------------------------------------------
 362→
 363→    /// Wallet backfill: topic-filtered ERC-20 Transfer logs.
 364→    ///
 365→    /// Uses topic-based filtering (wallet in topic\[1\] or topic\[2\]) instead
 366→    /// of the incorrect address filter. This returns Transfer events where
 367→    /// the wallet is the sender or receiver, regardless of which contract
 368→    /// emitted them.
 369→    ///
 370→    /// NOTE: Native ETH transfers without log events require block-scanning
 371→    /// or trace APIs. Tx-level value/from/to fields are still enriched onto
 372→    /// the first log per tx, which the parser uses for native value detection.
 373→    async fn wallet_backfill(
 374→        &self,
 375→        target: &IndexTarget,
 376→        cursor: Option<&serde_json::Value>,
 377→        limit: usize,
 378→    ) -> anyhow::Result<IngestionBatch> {
 379→        let wallet_str = target
 380→            .address
 381→            .as_deref()
 382→            .ok_or_else(|| anyhow::anyhow!("wallet target must have an address"))?;
 383→        let wallet_addr: Address = wallet_str.parse()?;
 384→
 385→        self.rate_limiter.until_ready().await;
 386→        let latest_block = self.provider.get_block_number().await?;
 387→
 388→        let from_block = cursor_to_from_block(cursor, latest_block, limit, self.block_chunk);
 389→
 390→        let logs = self
 391→            .fetch_wallet_erc20_logs(wallet_addr, from_block, latest_block)
 392→            .await?;
 393→
 394→        let enrichment = self.enrich_tx_data(&logs).await;
 395→        let records = self.logs_to_raw_transactions(&logs, &enrichment, "evm-rpc-wallet-backfill");
 396→
 397→        Ok(IngestionBatch {
 398→            records,
 399→            checkpoint: None,
 400→            run_metadata: None,
 401→        })
 402→    }
 403→
 404→    /// Contract backfill: address-filtered logs for a specific contract.
 405→    ///
 406→    /// Uses the standard address filter in `eth_getLogs`, which returns all
 407→    /// events emitted by the specified contract. This is the correct semantic
 408→    /// for contract target kinds.
 409→    async fn contract_backfill(
 410→        &self,
 411→        target: &IndexTarget,
 412→        cursor: Option<&serde_json::Value>,
 413→        limit: usize,
 414→    ) -> anyhow::Result<IngestionBatch> {
 415→        let contract_str = target
 416→            .address
 417→            .as_deref()
 418→            .ok_or_else(|| anyhow::anyhow!("contract target must have an address"))?;
 419→        let contract_addr: Address = contract_str.parse()?;
 420→
 421→        self.rate_limiter.until_ready().await;
 422→        let latest_block = self.provider.get_block_number().await?;
 423→
 424→        let from_block = cursor_to_from_block(cursor, latest_block, limit, self.block_chunk);
 425→
 426→        let logs = self
 427→            .fetch_logs(contract_addr, from_block, latest_block)
 428→            .await?;
 429→
 430→        let enrichment = self.enrich_tx_data(&logs).await;
 431→        let records =
 432→            self.logs_to_raw_transactions(&logs, &enrichment, "evm-rpc-contract-backfill");
 433→
 434→        Ok(IngestionBatch {
 435→            records,
 436→            checkpoint: None,
 437→            run_metadata: None,
 438→        })
 439→    }
 440→
 441→    /// Topic filter backfill: arbitrary topic-based log queries.
 442→    ///
 443→    /// Parses the `TopicFilterSpec` from the target's filter_spec and builds
 444→    /// the appropriate `eth_getLogs` filter. Supports optional address narrowing
 445→    /// via the spec's `address_filter` field.
 446→    async fn topic_filter_backfill(
 447→        &self,
 448→        _target: &IndexTarget,
 449→        spec: &TopicFilterSpec,
 450→        cursor: Option<&serde_json::Value>,
 451→        limit: usize,
 452→    ) -> anyhow::Result<IngestionBatch> {
 453→        self.rate_limiter.until_ready().await;
 454→        let latest_block = self.provider.get_block_number().await?;
 455→
 456→        let from_block = cursor_to_from_block(cursor, latest_block, limit, self.block_chunk);
 457→
 458→        // Parse topic positions from the spec
 459→        let topic0 = parse_topic_value(spec.topics.first())?;
 460→        let topic1 = parse_topic_value(spec.topics.get(1))?;
 461→        let topic2 = parse_topic_value(spec.topics.get(2))?;
 462→        let topic3 = parse_topic_value(spec.topics.get(3))?;
 463→
 464→        // Parse address filter
 465→        let addresses: Vec<Address> = spec
 466→            .address_filter
 467→            .iter()
 468→            .filter_map(|a| a.parse().ok())
 469→            .collect();
 470→
 471→        let logs = self
 472→            .fetch_logs_by_topics(
 473→                &addresses,
 474→                topic0,
 475→                topic1,
 476→                topic2,
 477→                topic3,
 478→                from_block,
 479→                latest_block,
 480→            )
 481→            .await?;
 482→
 483→        let enrichment = self.enrich_tx_data(&logs).await;
 484→        let records =
 485→            self.logs_to_raw_transactions(&logs, &enrichment, "evm-rpc-topic-filter-backfill");
 486→
 487→        Ok(IngestionBatch {
 488→            records,
 489→            checkpoint: None,
 490→            run_metadata: None,
 491→        })
 492→    }
 493→
 494→    // -----------------------------------------------------------------------
 495→    // Reorg detection (unchanged)
 496→    // -----------------------------------------------------------------------
 497→
 498→    /// Check block parent hash continuity for reorg detection.
 499→    /// Returns `Some(fork_block)` if a reorg is detected, starting from
 500→    /// the block where parent_hash diverges.
 501→    pub async fn detect_reorg(
 502→        &self,
 503→        known_blocks: &[(u64, B256)], // (block_num, block_hash) sorted ascending
 504→    ) -> anyhow::Result<Option<u64>> {
 505→        for (block_num, known_hash) in known_blocks.iter().rev() {
 506→            self.rate_limiter.until_ready().await;
 507→
 508→            if let Some(block) = self
 509→                .provider
 510→                .get_block_by_number((*block_num).into())
 511→                .await?
 512→            {
 513→                if block.header.hash != *known_hash {
 514→                    return Ok(Some(*block_num));
 515→                }
 516→            }
 517→        }
 518→        Ok(None)
 519→    }
 520→}
