 522→// ---------------------------------------------------------------------------
 523→// V2 Connector implementation
 524→// ---------------------------------------------------------------------------
 525→
 526→#[async_trait::async_trait]
 527→impl Connector for EvmAdapter {
 528→    fn capabilities(&self) -> ConnectorCapabilities {
 529→        ConnectorCapabilities {
 530→            supported_target_kinds: vec![
 531→                TargetKind::Wallet,
 532→                TargetKind::Contract,
 533→                TargetKind::TopicFilter,
 534→            ],
 535→            supported_modes: vec![TargetMode::Backfill],
 536→            chain_family: ChainFamily::Evm,
 537→        }
 538→    }
 539→
 540→    async fn backfill(
 541→        &self,
 542→        target: &IndexTarget,
 543→        cursor: Option<&serde_json::Value>,
 544→        limit: usize,
 545→    ) -> anyhow::Result<IngestionBatch> {
 546→        // Validate chain family
 547→        if target.chain_family != ChainFamily::Evm {
 548→            anyhow::bail!(
 549→                "EvmAdapter only supports EVM chain family, got {:?}",
 550→                target.chain_family
 551→            );
 552→        }
 553→
 554→        match target.kind {
 555→            TargetKind::Wallet => self.wallet_backfill(target, cursor, limit).await,
 556→            TargetKind::Contract => self.contract_backfill(target, cursor, limit).await,
 557→            TargetKind::TopicFilter => {
 558→                let typed = extract_filter_spec(target)?;
 559→                match typed {
 560→                    TypedFilterSpec::TopicFilter(spec) => {
 561→                        self.topic_filter_backfill(target, &spec, cursor, limit)
 562→                            .await
 563→                    }
 564→                    _ => anyhow::bail!("unexpected filter spec type for topic_filter target"),
 565→                }
 566→            }
 567→            other => anyhow::bail!(
 568→                "EvmAdapter does not support target kind {:?}; supported: wallet, contract, topic_filter",
 569→                other
 570→            ),
 571→        }
 572→    }
 573→}
