 592→
 593→        let from_block = if let Some(block) = checkpoint.and_then(|cp| cp.last_block) {
 594→            (block as u64).saturating_add(1)
 595→        } else {
 596→            let total_blocks = (limit as u64) * self.block_chunk;
 597→            latest_block.saturating_sub(total_blocks)
 598→        };
