 600→        let logs = self.fetch_logs(address, from_block, latest_block).await?;
 601→
 602→        let mut seen_tx_hashes: HashMap<String, (serde_json::Value, serde_json::Value)> =
 603→            HashMap::new();
 604→
 605→        for log in &logs {
 606→            let tx_hash_b256 = match log.transaction_hash {
 607→                Some(h) => h,
 608→                None => continue,
 609→            };
 610→            let tx_hash = format!("{tx_hash_b256:#x}");
 611→
 612→            if seen_tx_hashes.contains_key(&tx_hash) {
 613→                continue;
 614→            }
 615→
 616→            let mut tx_fields = json!({});
 617→            let mut receipt_fields = json!({});
 618→
 619→            self.rate_limiter.until_ready().await;
 620→            match self.provider.get_transaction_by_hash(tx_hash_b256).await {
 621→                Ok(Some(full_tx)) => {
 622→                    let value = full_tx.inner.value();
 623→                    let from = full_tx.inner.signer();
 624→                    let to = full_tx.inner.to().map(|a| format!("{a:#x}"));
 625→                    tx_fields = json!({
 626→                        "value": format!("{value:#x}"),
 627→                        "from": format!("{from:#x}"),
 628→                        "to": to,
 629→                    });
 630→                }
 631→                Ok(None) => {}
 632→                Err(e) => {
 633→                    warn!(tx_hash = %tx_hash, error = %e, "Failed to fetch transaction");
 634→                }
 635→            }
 636→
 637→            self.rate_limiter.until_ready().await;
 638→            match self.provider.get_transaction_receipt(tx_hash_b256).await {
 639→                Ok(Some(receipt)) => {
 640→                    receipt_fields = json!({
 641→                        "gas_used": format!("{:#x}", receipt.gas_used),
 642→                        "effective_gas_price": format!("{:#x}", receipt.effective_gas_price),
 643→                    });
 644→                }
 645→                Ok(None) => {}
 646→                Err(e) => {
 647→                    warn!(tx_hash = %tx_hash, error = %e, "Failed to fetch receipt");
 648→                }
 649→            }
 650→
 651→            seen_tx_hashes.insert(tx_hash, (tx_fields, receipt_fields));
 652→        }
 653→
 654→        let mut transactions = Vec::new();
 655→        let mut emitted_tx_hashes = HashSet::new();
 656→
 657→        for log in &logs {
 658→            let tx_hash = match log.transaction_hash {
 659→                Some(h) => format!("{h:#x}"),
 660→                None => continue,
 661→            };
 662→
 663→            let block_timestamp = log.block_timestamp.unwrap_or(0);
 664→
 665→            let mut raw_metadata = json!({
 666→                "log_index": log.log_index,
 667→                "block_number": log.block_number,
 668→                "block_hash": log.block_hash.map(|h| format!("{h:#x}")),
 669→                "transaction_hash": &tx_hash,
 670→                "address": format!("{:#x}", log.address()),
 671→                "topics": log.topics().iter().map(|t| format!("{t:#x}")).collect::<Vec<_>>(),
 672→                "data": format!("0x{}", alloy::hex::encode(log.data().data.as_ref())),
 673→            });
 674→
 675→            let is_first_log = emitted_tx_hashes.insert(tx_hash.clone());
 676→            if is_first_log {
 677→                if let Some((tx_fields, receipt_fields)) = seen_tx_hashes.get(&tx_hash) {
 678→                    if let Some(obj) = raw_metadata.as_object_mut() {
 679→                        if let Some(tx_obj) = tx_fields.as_object() {
 680→                            obj.extend(tx_obj.iter().map(|(k, v)| (k.clone(), v.clone())));
 681→                        }
 682→                        if let Some(rx_obj) = receipt_fields.as_object() {
 683→                            obj.extend(rx_obj.iter().map(|(k, v)| (k.clone(), v.clone())));
 684→                        }
 685→                    }
 686→                }
 687→            }
 688→
 689→            let timestamp = i64::try_from(block_timestamp).unwrap_or(i64::MAX);
 690→
 691→            transactions.push(Transaction {
 692→                id: Uuid::new_v4(),
 693→                user_id,
 694→                wallet_address: wallet.to_string(),
 695→                timestamp,
 696→                tx_hash,
 697→                chain: Chain::Ethereum,
 698→                raw_metadata,
 699→            });
 700→        }
 701→
 702→        Ok(transactions)
 703→    }
 704→}
