 706→// ---------------------------------------------------------------------------
 707→// Helpers
 708→// ---------------------------------------------------------------------------
 709→
 710→/// Parse a hex string into a B256 (32-byte hash).
 711→fn parse_b256(hex: &str) -> anyhow::Result<B256> {
 712→    let stripped = hex.strip_prefix("0x").unwrap_or(hex);
 713→    let bytes = alloy::hex::decode(stripped)?;
 714→    if bytes.len() != 32 {
 715→        anyhow::bail!("expected 32 bytes, got {}", bytes.len());
 716→    }
 717→    Ok(B256::from_slice(&bytes))
 718→}
 719→
 720→/// Left-pad an Ethereum address (20 bytes) to a 32-byte topic value.
 721→fn address_to_topic(addr: Address) -> B256 {
 722→    let mut bytes = [0u8; 32];
 723→    bytes[12..].copy_from_slice(addr.as_slice());
 724→    B256::from(bytes)
 725→}
 726→
 727→/// Parse a single topic value from a `TopicFilterSpec` topics array entry.
 728→///
 729→/// - `null` or missing → `None` (wildcard)
 730→/// - `"0x..."` → `Some(B256)` (exact match)
 731→/// - Arrays are not supported in this single-value path (would need FilterSet).
 732→fn parse_topic_value(val: Option<&serde_json::Value>) -> anyhow::Result<Option<B256>> {
 733→    match val {
 734→        None | Some(serde_json::Value::Null) => Ok(None),
 735→        Some(serde_json::Value::String(s)) => Ok(Some(parse_b256(s)?)),
 736→        Some(other) => anyhow::bail!("unsupported topic value type: {}", other),
 737→    }
 738→}
 739→
 740→/// Extract a starting block number from a V2 cursor, or compute a default.
 741→fn cursor_to_from_block(
 742→    cursor: Option<&serde_json::Value>,
 743→    latest_block: u64,
 744→    limit: usize,
 745→    block_chunk: u64,
 746→) -> u64 {
 747→    if let Some(c) = cursor {
 748→        if let Some(last_block) = c.get("last_block").and_then(|v| v.as_u64()) {
 749→            return last_block.saturating_add(1);
 750→        }
 751→        // V1 compat cursor
 752→        if let Some(last_block) = c.get("last_block").and_then(|v| v.as_i64()) {
 753→            if last_block >= 0 {
 754→                return (last_block as u64).saturating_add(1);
 755→            }
 756→        }
 757→    }
 758→    let total_blocks = (limit as u64) * block_chunk;
 759→    latest_block.saturating_sub(total_blocks)
 760→}
