  1→//! Compatibility layer for bridging V1 wallet-centric adapters to the V2
  2→//! target-driven `Connector` interface.
  3→//!
  4→//! This module provides:
  5→//!
  6→//! - `LegacyConnectorAdapter`: wraps a V1 `ChainIngestor` so it can be used
  7→//!   as a V2 `Connector` for wallet targets.
  8→//! - `legacy_wallet_target()`: synthesizes an `IndexTarget` from the legacy
  9→//!   (chain, wallet, user_id) parameters so existing CLI/API paths can route
 10→//!   through the new interface.
 11→//! - `v1_checkpoint_to_cursor()` / `cursor_to_v1_checkpoint()`: convert between
 12→//!   the V1 `IndexerCheckpoint` and the V2 opaque cursor JSON.
 13→
 14→use chrono::Utc;
 15→use spectraplex_core::connector::{Connector, ConnectorCapabilities};
 16→use spectraplex_core::models::{Chain, ChainIngestor, IndexerCheckpoint};
 17→use spectraplex_core::v2::{
 18→    ChainFamily, IndexTarget, IngestionBatch, RawTransaction, TargetKind, TargetMode,
 19→};
 20→use uuid::Uuid;
 21→
 22→// ---------------------------------------------------------------------------
 23→// Legacy wallet target construction
 24→// ---------------------------------------------------------------------------
 25→
 26→/// Map a V1 `Chain` enum to a (ChainFamily, network) pair.
 27→fn chain_to_family_and_network(chain: &Chain) -> (ChainFamily, &'static str) {
 28→    match chain {
 29→        Chain::Solana => (ChainFamily::Solana, "solana-mainnet"),
 30→        Chain::Ethereum => (ChainFamily::Evm, "ethereum-mainnet"),
 31→        Chain::Hyperliquid => (ChainFamily::Hyperliquid, "hypercore-mainnet"),
 32→    }
 33→}
 34→
 35→/// Map a chain string (as used in CLI) to a V1 `Chain` enum.
 36→fn chain_str_to_enum(chain: &str) -> Option<Chain> {
 37→    match chain {
 38→        "solana" => Some(Chain::Solana),
 39→        "ethereum" => Some(Chain::Ethereum),
 40→        "hyperliquid" => Some(Chain::Hyperliquid),
 41→        _ => None,
 42→    }
 43→}
 44→
 45→/// Synthesize a V2 `IndexTarget` from legacy (chain, wallet, user_id) parameters.
 46→///
 47→/// This allows existing CLI/API wallet-based calls to be expressed as target
 48→/// specs and routed through the V2 connector interface.
 49→pub fn legacy_wallet_target(
 50→    chain: &str,
 51→    wallet: &str,
 52→    owner_id: Option<Uuid>,
 53→) -> Option<IndexTarget> {
 54→    let chain_enum = chain_str_to_enum(chain)?;
 55→    let (family, network) = chain_to_family_and_network(&chain_enum);
 56→    let normalized_address = match family {
 57→        ChainFamily::Evm | ChainFamily::Hyperliquid => {
 58→            spectraplex_core::v2::normalize_evm_address(wallet)
 59→        }
 60→        ChainFamily::Solana => spectraplex_core::v2::normalize_solana_address(wallet),
 61→    };
 62→    let now = Utc::now();
 63→    Some(IndexTarget {
 64→        id: Uuid::new_v4(),
 65→        kind: TargetKind::Wallet,
 66→        network: network.to_string(),
 67→        chain_family: family,
 68→        address: Some(normalized_address),
 69→        filter_spec: None,
 70→        mode: TargetMode::Both,
 71→        label: Some(format!("Legacy wallet: {}", wallet)),
 72→        owner_id,
 73→        created_at: now,
 74→        updated_at: now,
 75→    })
 76→}
 77→
 78→/// Build a legacy `IndexTarget` from a `Chain` enum instead of a chain string.
 79→pub fn legacy_wallet_target_from_chain(
 80→    chain: &Chain,
 81→    wallet: &str,
 82→    owner_id: Option<Uuid>,
 83→) -> IndexTarget {
 84→    let (family, network) = chain_to_family_and_network(chain);
 85→    let normalized_address = match family {
 86→        ChainFamily::Evm | ChainFamily::Hyperliquid => {
 87→            spectraplex_core::v2::normalize_evm_address(wallet)
 88→        }
 89→        ChainFamily::Solana => spectraplex_core::v2::normalize_solana_address(wallet),
 90→    };
 91→    let now = Utc::now();
 92→    IndexTarget {
 93→        id: Uuid::new_v4(),
 94→        kind: TargetKind::Wallet,
 95→        network: network.to_string(),
 96→        chain_family: family,
 97→        address: Some(normalized_address),
 98→        filter_spec: None,
 99→        mode: TargetMode::Both,
100→        label: Some(format!("Legacy wallet: {}", wallet)),
101→        owner_id,
102→        created_at: now,
103→        updated_at: now,
104→    }
105→}
106→
107→// ---------------------------------------------------------------------------
108→// Checkpoint conversion
109→// ---------------------------------------------------------------------------
110→
111→/// Convert a V1 `IndexerCheckpoint` to a V2 opaque cursor JSON.
112→pub fn v1_checkpoint_to_cursor(cp: &IndexerCheckpoint) -> serde_json::Value {
113→    serde_json::json!({
114→        "v1_compat": true,
115→        "last_signature": cp.last_signature,
116→        "last_slot": cp.last_slot,
117→        "last_block": cp.last_block,
118→        "last_timestamp": cp.last_timestamp,
119→    })
120→}
121→
122→/// Convert a V2 opaque cursor JSON back to a V1 `IndexerCheckpoint`.
123→///
124→/// Returns `None` if the cursor is not a V1-compatible checkpoint.
125→pub fn cursor_to_v1_checkpoint(
126→    chain: &str,
127→    wallet: &str,
128→    cursor: &serde_json::Value,
129→) -> Option<IndexerCheckpoint> {
130→    if !cursor.get("v1_compat")?.as_bool()? {
131→        return None;
132→    }
133→    let chain_enum = chain_str_to_enum(chain)?;
134→    Some(IndexerCheckpoint {
135→        chain: chain_enum,
136→        wallet_address: wallet.to_string(),
137→        last_signature: cursor
138→            .get("last_signature")
139→            .and_then(|v| v.as_str())
140→            .map(|s| s.to_string()),
141→        last_slot: cursor.get("last_slot").and_then(|v| v.as_i64()),
142→        last_block: cursor.get("last_block").and_then(|v| v.as_i64()),
143→        last_timestamp: cursor.get("last_timestamp").and_then(|v| v.as_i64()),
144→    })
145→}
146→
147→// ---------------------------------------------------------------------------
148→// LegacyConnectorAdapter
149→// ---------------------------------------------------------------------------
150→
151→/// Wraps a V1 `ChainIngestor` to present it as a V2 `Connector`.
152→///
153→/// Only wallet targets are supported. The adapter:
154→/// 1. Extracts the wallet address from the `IndexTarget`
155→/// 2. Converts the V2 cursor to a V1 checkpoint
156→/// 3. Calls `ChainIngestor::fetch_history`
157→/// 4. Converts the V1 `Transaction` results to V2 `RawTransaction`s
158→pub struct LegacyConnectorAdapter<I: ChainIngestor + Send + Sync> {
159→    ingestor: I,
160→    chain_family: ChainFamily,
161→    network: String,
162→    chain_str: String,
163→}
164→
165→impl<I: ChainIngestor + Send + Sync> LegacyConnectorAdapter<I> {
166→    pub fn new(ingestor: I, chain: &Chain) -> Self {
167→        let (family, network) = chain_to_family_and_network(chain);
168→        let chain_str = match chain {
169→            Chain::Solana => "solana",
170→            Chain::Ethereum => "ethereum",
171→            Chain::Hyperliquid => "hyperliquid",
172→        };
173→        Self {
174→            ingestor,
175→            chain_family: family,
176→            network: network.to_string(),
177→            chain_str: chain_str.to_string(),
178→        }
179→    }
180→}
181→
182→/// Convert a V1 `Transaction` to a V2 `RawTransaction`.
183→fn v1_tx_to_raw(tx: &spectraplex_core::models::Transaction, network: &str) -> RawTransaction {
184→    RawTransaction {
185→        id: Uuid::new_v4(),
186→        network: network.to_string(),
187→        tx_hash: tx.tx_hash.clone(),
188→        timestamp: tx.timestamp,
189→        block_number: tx
190→            .raw_metadata
191→            .get("block_number")
192→            .and_then(|v| v.as_i64())
193→            .or_else(|| tx.raw_metadata.get("slot").and_then(|v| v.as_i64())),
194→        raw_metadata: tx.raw_metadata.clone(),
195→        source: "legacy-compat".to_string(),
196→        ingestion_run_id: None,
197→        ingested_at: Utc::now(),
198→    }
199→}
200→
201→#[async_trait::async_trait]
202→impl<I: ChainIngestor + Send + Sync> Connector for LegacyConnectorAdapter<I> {
203→    fn capabilities(&self) -> ConnectorCapabilities {
204→        ConnectorCapabilities {
205→            supported_target_kinds: vec![TargetKind::Wallet],
206→            supported_modes: vec![TargetMode::Backfill],
207→            chain_family: self.chain_family,
208→        }
209→    }
210→
211→    async fn backfill(
212→        &self,
213→        target: &IndexTarget,
214→        cursor: Option<&serde_json::Value>,
215→        limit: usize,
216→    ) -> anyhow::Result<IngestionBatch> {
217→        // Validate target kind
218→        if target.kind != TargetKind::Wallet {
219→            anyhow::bail!(
220→                "LegacyConnectorAdapter only supports wallet targets, got {:?}",
221→                target.kind
222→            );
223→        }
224→
225→        // Extract wallet address
226→        let wallet = target
227→            .address
228→            .as_deref()
229→            .ok_or_else(|| anyhow::anyhow!("wallet target must have an address"))?;
230→
231→        // Convert cursor to V1 checkpoint
232→        let v1_checkpoint =
233→            cursor.and_then(|c| cursor_to_v1_checkpoint(&self.chain_str, wallet, c));
234→
235→        // Use a nil user_id since V2 does not embed consumer identity in Bronze
236→        let user_id = target.owner_id.unwrap_or(Uuid::nil());
237→
238→        // Call the legacy ingestor
239→        let v1_txs = self
240→            .ingestor
241→            .fetch_history(wallet, limit, user_id, v1_checkpoint.as_ref())
242→            .await?;
243→
244→        // Convert V1 transactions to V2 raw transactions
245→        let records: Vec<RawTransaction> = v1_txs
246→            .iter()
247→            .map(|tx| v1_tx_to_raw(tx, &self.network))
248→            .collect();
249→
250→        Ok(IngestionBatch {
251→            records,
252→            checkpoint: None,
253→            run_metadata: None,
254→        })
255→    }
256→}
