 26→/// Configuration for the gRPC streaming adapter.
 27→pub struct GrpcStreamConfig {
 28→    pub endpoint: String,
 29→    pub x_token: Option<String>,
 30→    pub program_ids: Vec<String>,
 31→    pub commitment: CommitmentLevel,
 32→    pub max_retries: u32,
 33→    pub channel_capacity: usize,
 34→}
 35→
 36→impl Default for GrpcStreamConfig {
 37→    fn default() -> Self {
 38→        Self {
 39→            endpoint: String::new(),
 40→            x_token: None,
 41→            program_ids: DEFAULT_PROGRAM_IDS.iter().map(|s| s.to_string()).collect(),
 42→            commitment: CommitmentLevel::Confirmed,
 43→            max_retries: 10,
 44→            channel_capacity: 10_000,
 45→        }
 46→    }
 47→}
