fn build_target_subscribe_request(
    target: &IndexTarget,
    commitment: CommitmentLevel,
    from_slot: Option<u64>,
) -> anyhow::Result<SubscribeRequest> {
    let address = target
        .address
        .as_deref()
        .ok_or_else(|| anyhow::anyhow!("{:?} target must have an address", target.kind))?;

